router.post('/cart/transfer', async (req, res) => {
  const targetCartId = req.headers['x-target-cart'];
  const targetCart = await db.collection('carts').doc(targetCartId).get();
  if (targetCart.data().ownerId !== req.user.id) {
    return res.status(403).send('Unauthorized cart access');
  }
  const items = targetCart.data().items;
  const userCartRef = db.collection('carts').doc(req.user.cartId);
  const userCart = await userCartRef.get();
  const currentItems = (userCart.exists && userCart.data().items) || [];
  await userCartRef.update({ items: currentItems.concat(items) });
  await db.collection('carts').doc(targetCartId).update({ items: [] });
  res.send('Transferred');
});
